/* ------------------------------ game state ------------------------------ */

const state = {
  mode: 'menu', // menu | playing | paused | ended
  score: 0, opp: 0, makes: 0, attempts: 0, streak: 0,
  gameTime: 60, shotClock: 24,
  charge: 0, charging: false, chargeDir: 1,
  shot: null, shootAnim: 0, pressure: 0,
  netPulse: 0, crowdPulse: 0, cameraShake: 0, rimFlash: 0,
  toastTimer: 0, ballResetTimer: 0, loose: false
};

const ballVel = new THREE.Vector3();
const handTarget = new THREE.Vector3();
let audioCtx = null;

function beep(freq = 520, dur = 0.08, type = 'sine', vol = 0.035) {
  try {
    audioCtx ??= new (window.AudioContext || window.webkitAudioContext)();
    const o = audioCtx.createOscillator(), g = audioCtx.createGain();
    o.type = type;
    o.frequency.value = freq;
    g.gain.value = vol;
    g.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + dur);
    o.connect(g);
    g.connect(audioCtx.destination);
    o.start();
    o.stop(audioCtx.currentTime + dur);
  } catch (e) { /* audio is optional */ }
}

function distToHoop() {
  return Math.hypot(player.x - HOOP.x, player.z - HOOP.z);
}

function contestAmount() {
  const d = Math.hypot(player.x - defender.x, player.z - defender.z);
  return Math.max(0, Math.min(1, 1 - (d - 0.8) / 2.3));
}

function formatTime(n) {
  n = Math.max(0, Math.ceil(n));
  return `${Math.floor(n / 60)}:${String(n % 60).padStart(2, '0')}`;
}

function updateUI() {
  ui.score.textContent = String(state.score).padStart(2, '0');
  ui.opp.textContent = String(state.opp).padStart(2, '0');
  ui.time.textContent = formatTime(state.gameTime);
  ui.fg.textContent = `${state.makes} / ${state.attempts}`;
  ui.streak.textContent = state.streak ? `${state.streak}×` : '—';
  ui.shot.textContent = Math.max(0, Math.ceil(state.shotClock));
  ui.shotclock.classList.toggle('hot', state.shotClock <= 5);
  ui.fill.style.width = `${Math.min(state.charge, 1) * 100}%`;
  ui.meter.classList.toggle('active', state.charging);
  if (state.charging) {
    ui.label.textContent = state.charge >= 0.78 && state.charge <= 0.9 ? 'PERFECT WINDOW' : state.charge > 0.9 ? 'RELEASE!' : 'BUILD POWER';
  } else {
    ui.label.textContent = distToHoop() > 6.75 ? '3PT RANGE' : 'TWO-POINT RANGE';
  }
}

function showToast(text, bad = false) {
  ui.toast.textContent = text;
  ui.toast.classList.toggle('bad', bad);
  ui.toast.classList.add('show');
  clearTimeout(state.toastTimer);
  state.toastTimer = setTimeout(() => ui.toast.classList.remove('show'), 1100);
}

function popScore(el) {
  el.classList.add('pop');
  setTimeout(() => el.classList.remove('pop'), 220);
}

function resetPositions() {
  player.x = 0; player.z = 1.5; player.vx = 0; player.vz = 0;
  defender.x = 0; defender.z = -2.4; defender.vx = 0; defender.vz = 0;
  state.pressure = 0;
  state.loose = false;
  state.ballResetTimer = 0;
  state.shot = null;
  state.charging = false;
  state.charge = 0;
  state.chargeDir = 1;
  ballVel.set(0, 0, 0);
  hideOverlay();
}

function startGame() {
  state.mode = 'playing';
  state.score = 0; state.opp = 0; state.makes = 0; state.attempts = 0; state.streak = 0;
  state.gameTime = 60; state.shotClock = 24;
  state.shootAnim = 0; state.netPulse = 0; state.crowdPulse = 0; state.cameraShake = 0;
  resetPositions();
  gameEl.classList.add('active');
  ui.pause.textContent = 'Ⅱ  PAUSE';
  updateUI();
}

function endGame() {
  state.mode = 'ended';
  state.charging = false;
  ui.meter.classList.remove('active');
  gameEl.classList.remove('active');
  const best = Math.max(state.score, Number(localStorage.getItem('courtside-3d-best') || 0));
  localStorage.setItem('courtside-3d-best', best);
  const won = state.score > state.opp;
  ui.eyebrow.textContent = won ? 'RUN COMPLETE · W' : 'RUN COMPLETE · FINAL';
  ui.title.innerHTML = won ? 'THAT\'S A<span>W.</span>' : 'RUN IT<span>BACK.</span>';
  ui.deck.textContent = `Final: ${state.score}–${state.opp}. You knocked down ${state.makes} of ${state.attempts} shots${state.attempts ? ` (${Math.round(state.makes / state.attempts * 100)}% FG)` : ''}.`;
  ui.result.textContent = `BEST SCORE  ${best}  ·  ${won ? 'YOU OWNED THE COURT.' : 'THE COURT IS STILL YOURS TO TAKE.'}`;
  ui.play.innerHTML = 'PLAY AGAIN <span class="arrow">↗</span>';
  showOverlay();
}

function pauseGame() {
  if (state.mode === 'playing') {
    state.mode = 'paused';
    state.charging = false;
    ui.meter.classList.remove('active');
    gameEl.classList.remove('active');
    ui.eyebrow.textContent = 'TIMEOUT · TAKE A BREATH';
    ui.title.innerHTML = 'CATCH<span>YOUR BREATH.</span>';
    ui.deck.textContent = 'The run is paused. Your score, streak, and shot clock are waiting.';
    ui.result.textContent = `${state.score}–${state.opp}  ·  ${formatTime(state.gameTime)} REMAINING`;
    ui.play.innerHTML = 'RESUME RUN <span class="arrow">↗</span>';
    showOverlay();
  } else if (state.mode === 'paused') {
    state.mode = 'playing';
    hideOverlay();
    gameEl.classList.add('active');
    ui.pause.textContent = 'Ⅱ  PAUSE';
  }
}

function showOverlay() {
  ui.overlay.classList.remove('hidden');
}

function hideOverlay() {
  ui.overlay.classList.add('hidden');
}

/* ------------------------------ shooting ------------------------------ */

function beginShot() {
  if (state.mode !== 'playing' || state.charging || state.shot || state.loose) return;
  state.charging = true;
  state.charge = 0;
  state.chargeDir = 1;
  state.shootAnim = 0;
  beep(300, 0.06, 'triangle', 0.012);
  updateUI();
}

function releaseShot() {
  if (!state.charging) return;
  state.charging = false;
  ui.meter.classList.remove('active');
  state.attempts++;
  state.shotClock = 24;

  const d = distToHoop();
  const worth = d > 6.75 ? 3 : 2;
  const timing = 1 - Math.min(1, Math.abs(state.charge - 0.84) / 0.42);
  const green = state.charge >= 0.78 && state.charge <= 0.9;
  const contest = contestAmount();
  const rangePenalty = Math.max(0, d - 6.0) * 0.027;
  const chance = Math.max(0.27, Math.min(0.96, 0.92 - rangePenalty - contest * 0.38));
  const made = green || Math.random() < chance;

  const start = new THREE.Vector3(player.x + 0.14, 1.92 + state.charge * 0.34, player.z - 0.4);
  const end = HOOP.clone();
  if (made) {
    end.x += (Math.random() - 0.5) * 0.05;
    end.z += (Math.random() - 0.5) * 0.05;
    end.y += 0.01;
  } else {
    const side = Math.random() < 0.5 ? -1 : 1;
    end.x += side * (0.34 + Math.random() * 0.28);
    end.z += 0.18 + Math.random() * 0.2;
    end.y += (Math.random() - 0.5) * 0.12;
  }

  state.shot = {
    phase: 'flight', t: 0,
    dur: 0.74 + Math.min(d, 9) * 0.035,
    start, end,
    arc: 0.85 + d * 0.075 + contest * 0.15,
    made, worth, green
  };
  state.shootAnim = 1;
  if (green) { showToast('PERFECT RELEASE'); beep(820, 0.09, 'sine', 0.03); }
  else if (!made) { showToast('OFF THE RIM', true); }
  beep(made ? 420 : 240, 0.07, 'triangle', 0.02);
  updateUI();
}

function scoreMake(shot) {
  state.score += shot.worth;
  state.makes++;
  state.streak++;
  state.netPulse = 1;
  state.crowdPulse = 1;
  state.cameraShake = 0.16;
  state.rimFlash = 1;
  burst(HOOP.clone());
  const text = shot.green
    ? (shot.worth === 3 ? 'GREEN · FROM DEEP' : 'GREEN · CASH')
    : (shot.worth === 3 ? 'THREE FROM DOWNTOWN' : 'BUCKET');
  showToast(text);
  popScore(ui.score);
  beep(shot.worth === 3 ? 920 : 690, 0.18, 'sine', 0.055);
  setTimeout(() => beep(shot.worth === 3 ? 1180 : 880, 0.14, 'sine', 0.035), 90);
}

function scoreMiss() {
  state.streak = 0;
  showToast('NO GOOD · GET IT BACK', true);
  beep(150, 0.16, 'square', 0.018);
}

/* ------------------------------ input ------------------------------ */

const keys = { up: false, down: false, left: false, right: false, sprint: false };
const touch = { x: 0, y: 0 };

window.addEventListener('keydown', (e) => {
  const k = e.key.toLowerCase();
  if ([' ', 'arrowup', 'arrowdown', 'arrowleft', 'arrowright'].includes(k)) e.preventDefault();
  if (k === 'escape' || k === 'p') { pauseGame(); return; }
  if (['w', 'arrowup'].includes(k)) keys.up = true;
  if (['s', 'arrowdown'].includes(k)) keys.down = true;
  if (['a', 'arrowleft'].includes(k)) keys.left = true;
  if (['d', 'arrowright'].includes(k)) keys.right = true;
  if (k === 'shift') keys.sprint = true;
  if ((k === ' ' || k === 'enter') && !e.repeat) beginShot();
});
window.addEventListener('keyup', (e) => {
  const k = e.key.toLowerCase();
  if (['w', 'arrowup'].includes(k)) keys.up = false;
  if (['s', 'arrowdown'].includes(k)) keys.down = false;
  if (['a', 'arrowleft'].includes(k)) keys.left = false;
  if (['d', 'arrowright'].includes(k)) keys.right = false;
  if (k === 'shift') keys.sprint = false;
  if (k === ' ') releaseShot();
});
window.addEventListener('blur', () => {
  keys.up = keys.down = keys.left = keys.right = keys.sprint = false;
  if (state.charging) releaseShot();
});

ui.play.addEventListener('click', () => {
  if (state.mode === 'paused') pauseGame();
  else startGame();
});
ui.pause.addEventListener('click', pauseGame);

// touch stick
const stick = document.getElementById('stick');
const nub = document.getElementById('nub');
let stickPointer = null;

function stickMove(e) {
  const r = stick.getBoundingClientRect();
  const cx = r.left + r.width / 2, cy = r.top + r.height / 2;
  const dx = e.clientX - cx, dy = e.clientY - cy;
  const max = r.width * 0.36;
  const d = Math.hypot(dx, dy) || 1;
  const s = Math.min(1, max / d);
  touch.x = dx * s / max;
  touch.y = dy * s / max;
  nub.style.left = `${50 + touch.x * 36}%`;
  nub.style.top = `${50 + touch.y * 36}%`;
}
function resetStick() {
  stickPointer = null;
  touch.x = touch.y = 0;
  nub.style.left = '50%';
  nub.style.top = '50%';
}
stick.addEventListener('pointerdown', (e) => { stickPointer = e.pointerId; stick.setPointerCapture(stickPointer); stickMove(e); });
stick.addEventListener('pointermove', (e) => { if (e.pointerId === stickPointer) stickMove(e); });
stick.addEventListener('pointerup', resetStick);
stick.addEventListener('pointercancel', resetStick);

const shootBtn = document.getElementById('shoot-touch');
shootBtn.addEventListener('pointerdown', (e) => { e.preventDefault(); shootBtn.setPointerCapture(e.pointerId); beginShot(); });
shootBtn.addEventListener('pointerup', (e) => { e.preventDefault(); releaseShot(); });
shootBtn.addEventListener('pointercancel', releaseShot);

window.addEventListener('resize', () => {
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.8));
  renderer.setSize(window.innerWidth, window.innerHeight);
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
});
