/* ------------------------------ gameplay update ------------------------------ */

function updatePlayer(dt) {
  let ix = (keys.right ? 1 : 0) - (keys.left ? 1 : 0) + touch.x;
  let iz = (keys.down ? 1 : 0) - (keys.up ? 1 : 0) + touch.y;
  const mag = Math.hypot(ix, iz);
  if (mag > 1) { ix /= mag; iz /= mag; }
  const speed = keys.sprint ? 5.2 : 3.7;
  const accel = Math.min(1, dt * 10);
  player.vx += (ix * speed - player.vx) * accel;
  player.vz += (iz * speed - player.vz) * accel;

  if (!state.shot) {
    player.x = Math.max(-6.95, Math.min(6.95, player.x + player.vx * dt));
    player.z = Math.max(-11.1, Math.min(1.7, player.z + player.vz * dt));
  } else {
    player.vx *= 0.86;
    player.vz *= 0.86;
  }
}

function updateDefender(dt, t) {
  let gx, gz;
  if (state.shot) {
    gx = 0; gz = -11.2;
  } else {
    const dx = HOOP.x - player.x, dz = HOOP.z - player.z;
    const len = Math.hypot(dx, dz) || 1;
    const wiggle = Math.sin(t * 1.7) * 0.34;
    gx = player.x + (dx / len) * 1.08 - (dz / len) * wiggle;
    gz = player.z + (dz / len) * 1.08 + (dx / len) * wiggle;
  }
  const dx = gx - defender.x, dz = gz - defender.z;
  const len = Math.hypot(dx, dz) || 1;
  const sp = state.shot ? 4.6 : 3.15;
  const accel = Math.min(1, dt * 4.2);
  defender.vx += ((dx / len) * sp - defender.vx) * accel;
  defender.vz += ((dz / len) * sp - defender.vz) * accel;
  defender.x = Math.max(-6.9, Math.min(6.9, defender.x + defender.vx * dt));
  defender.z = Math.max(-11.4, Math.min(1.6, defender.z + defender.vz * dt));

  // keep bodies from overlapping
  const ox = player.x - defender.x, oz = player.z - defender.z;
  const od = Math.hypot(ox, oz);
  if (od > 0.001 && od < 0.78) {
    const push = (0.78 - od) * 0.5;
    player.x += (ox / od) * push;
    player.z += (oz / od) * push;
    defender.x -= (ox / od) * push;
    defender.z -= (oz / od) * push;
  }
}

function animateRig(rig, p, dt, opts = {}) {
  const sp = Math.hypot(p.vx, p.vz);
  p.phase += dt * (2.1 + sp * 2.5);
  const amt = Math.min(1, sp / 3.4);
  const swing = Math.sin(p.phase) * 0.7 * amt;
  const [l, r] = rig.legs;
  l.hip.rotation.x = swing;
  r.hip.rotation.x = -swing;
  l.knee.rotation.x = Math.max(0, -Math.sin(p.phase)) * 0.9 * amt;
  r.knee.rotation.x = Math.max(0, Math.sin(p.phase)) * 0.9 * amt;

  rig.root.position.y = 0.015 + Math.abs(Math.sin(p.phase * 2)) * 0.035 * amt;
  rig.torso.rotation.x = 0.02 + 0.07 * amt;
}

function posePlayer(dt) {
  animateRig(playerRig, player, dt);
  const root = playerRig.root;
  root.position.x = player.x;
  root.position.z = player.z;
  const face = Math.atan2(-(HOOP.x - player.x), -(HOOP.z - player.z));
  root.rotation.y = face - player.vx * 0.035;

  const raise = state.charging ? state.charge : state.shootAnim;
  const [lArm, rArm] = playerRig.arms;
  const sp = Math.hypot(player.vx, player.vz);
  const amt = Math.min(1, sp / 3.4);
  const swing = Math.sin(player.phase) * 0.3 * amt * (1 - raise);

  rArm.shoulder.rotation.x = 0.14 + raise * 2.2 + swing;
  rArm.shoulder.rotation.z = -0.12 - raise * 0.15;
  rArm.elbow.rotation.x = -0.28 - raise * 0.35;

  lArm.shoulder.rotation.x = 0.14 + raise * 1.35 - swing;
  lArm.shoulder.rotation.z = 0.12 + raise * 0.35;
  lArm.elbow.rotation.x = -0.28 - raise * 0.25;

  playerRig.ring.material.opacity = 0.34 + Math.sin(clock.elapsedTime * 4) * 0.08;
}

function poseDefender(dt) {
  animateRig(defenderRig, defender, dt);
  const root = defenderRig.root;
  root.position.x = defender.x;
  root.position.z = defender.z;
  const dx = player.x - defender.x, dz = player.z - defender.z;
  const face = Math.atan2(-dx, -dz);
  root.rotation.y = face;

  const contest = !state.shot && contestAmount() > 0.15;
  const up = state.shot && state.shot.phase === 'flight' ? 1 : contest ? 0.85 : 0.15;
  const bob = Math.sin(clock.elapsedTime * 6.5) * 0.05;
  const [lArm, rArm] = defenderRig.arms;
  lArm.shoulder.rotation.x = 0.16 + up * 2.5 + bob;
  rArm.shoulder.rotation.x = 0.16 + up * 2.5 - bob;
  lArm.shoulder.rotation.z = 0.24 + up * 0.15;
  rArm.shoulder.rotation.z = -0.24 - up * 0.15;
  lArm.elbow.rotation.x = -0.3 - up * 0.25;
  rArm.elbow.rotation.x = -0.3 - up * 0.25;
}

function shotClockViolation() {
  state.opp += 2;
  state.streak = 0;
  state.shotClock = 24;
  popScore(ui.opp);
  showToast('SHOT CLOCK · +2 COURT', true);
  beep(120, 0.3, 'sawtooth', 0.025);
  resetPositions();
  updateUI();
}

function turnover() {
  state.opp += 2;
  state.streak = 0;
  state.pressure = 0;
  state.shotClock = 14;
  state.cameraShake = 0.1;
  popScore(ui.opp);
  showToast('STRIPPED · +2 COURT', true);
  beep(110, 0.16, 'square', 0.03);
  resetPositions();
  updateUI();
}

function updatePressure(dt) {
  if (state.shot) {
    state.pressure = Math.max(0, state.pressure - dt * 2);
    return;
  }
  const d = Math.hypot(player.x - defender.x, player.z - defender.z);
  if (d < 1.18) state.pressure += dt;
  else state.pressure = Math.max(0, state.pressure - dt * 1.7);
  if (state.pressure > 2.1 && !state.pressureWarned) {
    state.pressureWarned = true;
    showToast('GET SEPARATION', true);
  }
  if (state.pressure > 3.9) {
    state.pressureWarned = false;
    turnover();
  }
  if (state.pressure < 1) state.pressureWarned = false;
}

function updateBall(dt, t) {
  state.shootAnim = Math.max(0, state.shootAnim - dt * 2.4);

  if (state.shot) {
    const s = state.shot;
    if (s.phase === 'flight') {
      s.t += dt;
      const p = Math.min(1, s.t / s.dur);
      ball.position.lerpVectors(s.start, s.end, p);
      ball.position.y += Math.sin(Math.PI * p) * s.arc;
      ball.rotation.x -= dt * 16;
      ball.rotation.z += dt * 3.5;
      if (p >= 1) {
        if (s.made) {
          scoreMake(s);
          s.phase = 'drop';
          s.timer = 0;
          ballVel.set(0, -1.1, 0.45);
        } else {
          scoreMiss();
          s.phase = 'loose';
          s.timer = 0;
          ballVel.set((Math.random() - 0.5) * 3.4, 1.3, 3.2 + Math.random());
        }
      }
    } else {
      s.timer += dt;
      ballVel.y -= 12 * dt;
      ball.position.addScaledVector(ballVel, dt);
      ball.rotation.x -= dt * 12;
      ball.rotation.z += dt * 4;
      const floorY = 0.122;
      if (ball.position.y < floorY) {
        ball.position.y = floorY;
        if (ballVel.y < 0) ballVel.y = Math.abs(ballVel.y) * 0.56;
        ballVel.x *= 0.75;
        ballVel.z *= 0.75;
        if (Math.abs(ballVel.y) < 0.55) ballVel.y = 0;
      }
      if (s.timer > (s.phase === 'drop' ? 1.1 : 1.7)) {
        state.shot = null;
        state.loose = false;
      }
    }
    return;
  }

  if (state.charging) {
    ball.position.set(player.x + 0.16, 1.62 + state.charge * 0.5, player.z - 0.35);
    ball.rotation.x -= dt * 2;
    return;
  }

  // live dribble
  const bounce = Math.abs(Math.sin(t * 5.8));
  ball.position.set(player.x + 0.42, 0.125 + bounce * 0.72, player.z + 0.12);
  ball.rotation.x -= dt * (7 + bounce * 9);
  ball.rotation.z += dt * 1.6;
}

function updateEffects(dt, t) {
  state.netPulse = Math.max(0, state.netPulse - dt * 2.3);
  state.crowdPulse = Math.max(0, state.crowdPulse - dt * 1.4);
  state.cameraShake = Math.max(0, state.cameraShake - dt * 1.4);
