    for (let i = 0; i < PARTICLE_COUNT; i++) {
      pVel[i].y -= 7.5 * dt;
      pPositions[i * 3] += pVel[i].x * dt;
      pPositions[i * 3 + 1] += pVel[i].y * dt;
      pPositions[i * 3 + 2] += pVel[i].z * dt;
    }
    pGeo.attributes.position.needsUpdate = true;
