.rules{display:flex;gap:22px;margin-top:30px;padding-top:18px;border-top:1px solid #ffffff20}
.rule{color:#95a39a;font-size:9px;letter-spacing:.12em;line-height:1.45}
.rule b{display:block;color:#e4e9e0;font-size:10px;margin-bottom:5px}
.result{font-size:12px;color:#b8c5bb;line-height:1.7;min-height:38px;margin-top:-8px;margin-bottom:18px}
.build-tag{display:inline-flex;align-items:center;gap:7px;color:#0b1410;background:#d8ff3e;border-radius:3px;padding:4px 8px;font-size:9px;font-weight:950;letter-spacing:.14em;margin-bottom:16px}

/* 2K-style shot meter beside the player */
.side-meter{position:absolute;z-index:6;width:70px;display:none;pointer-events:none;transform:translate(-50%,-50%);filter:drop-shadow(0 4px 8px #0008)}
.side-meter.show{display:block}
.sm-quality{font-size:8px;font-weight:950;letter-spacing:.13em;text-align:center;color:var(--lime);margin-bottom:4px;text-shadow:0 2px 4px #000}
.sm-body{display:flex;justify-content:flex-end;align-items:flex-end;gap:5px}
.sm-caption{writing-mode:vertical-rl;text-orientation:mixed;font-size:7px;font-weight:900;letter-spacing:.2em;color:#c9d6c8;transform:rotate(180deg);text-shadow:0 2px 4px #000}
.sm-track{position:relative;width:11px;height:118px;border-radius:6px;border:1px solid #e9f2df8f;background:#071313d9;box-shadow:0 0 12px #000a;overflow:visible}
.sm-fill{position:absolute;left:1px;right:1px;bottom:1px;height:0;border-radius:5px;background:linear-gradient(0deg,#ff6d55 0%,#ffd64b 68%,#d8ff3e 100%);box-shadow:0 0 10px #d8ff3e66}
.sm-window{position:absolute;left:-4px;right:-4px;background:#d8ff3e2e;border-top:1px solid #efffd0;border-bottom:1px solid #efffd0;box-shadow:0 0 12px #d8ff3e55}
.sm-label{margin-top:4px;text-align:center;font-size:7px;font-weight:950;letter-spacing:.12em;color:#dfe8db;text-shadow:0 2px 4px #000}

/* floating player tags */
#tags{position:absolute;inset:0;z-index:3;overflow:hidden;pointer-events:none}
.tag{position:absolute;left:0;top:0;transform:translate(-50%,-100%);padding:2px 6px;border-radius:3px;background:#071313b8;border:1px solid #ffffff24;font-size:8px;font-weight:900;letter-spacing:.09em;white-space:nowrap;color:#dce8da;opacity:0;transition:opacity .18s;text-shadow:0 1px 3px #000}
.tag.show{opacity:1}
.tag.home{color:#d8ff3e}
.tag.away{color:#ff8d78}
.tag.active{border-color:#d8ff3e;background:#0a1a12e0;box-shadow:0 0 12px #d8ff3e3d}
.tag small{color:#a6b4a6;font-size:7px;margin-left:3px;font-weight:800}
.tag .scr{color:#fff;background:#d8ff3e;color:#09110b;border-radius:2px;padding:0 3px;margin-left:3px}

#shot-feedback{position:absolute;z-index:6;transform:translate(-50%,-100%);font-size:23px;font-weight:950;letter-spacing:.06em;opacity:0;transition:.18s;pointer-events:none;text-shadow:0 3px 10px #000;white-space:nowrap}
#shot-feedback.show{opacity:1}
#shot-feedback.green{color:#d8ff3e}
#shot-feedback.bad{color:#ff8068}
#shot-feedback small{display:block;text-align:center;font-size:8px;letter-spacing:.16em;color:#d7e3d4;font-weight:800;margin-top:3px}

/* touch */
.touch-controls{display:none;position:absolute;z-index:5;inset:auto 0 18px;justify-content:space-between;align-items:flex-end;padding:0 24px;pointer-events:none}
.stick{width:112px;height:112px;border-radius:50%;border:1px solid #ffffff3d;background:#0919189c;position:relative;pointer-events:auto;touch-action:none}
.stick:before{content:"";position:absolute;inset:27px;border:1px solid #ffffff21;border-radius:50%}
.nub{position:absolute;width:37px;height:37px;left:50%;top:50%;transform:translate(-50%,-50%);border-radius:50%;background:#d8ff3e;border:3px solid #ffffffaa;box-shadow:0 2px 14px #0009}
.shoot-touch{pointer-events:auto;width:82px;height:82px;border-radius:50%;border:2px solid #d8ff3e;background:#d8ff3e24;color:var(--lime);font-size:10px;font-weight:950;letter-spacing:.1em;box-shadow:0 0 25px #d8ff3e21;touch-action:none}
.touch-actions{display:none;position:absolute;z-index:5;right:20px;bottom:112px;grid-template-columns:1fr 1fr;gap:7px;pointer-events:auto}
.mini-btn{width:60px;height:34px;border-radius:6px;border:1px solid #ffffff45;background:#071313c9;color:#e6ede1;font-size:8px;font-weight:950;letter-spacing:.08em;touch-action:none}
.mini-btn:active{background:#d8ff3e;color:#09110b}
.mobile-tip{display:none;color:#b2bdb2;font-size:9px;text-align:center;line-height:1.5;letter-spacing:.1em;margin-bottom:7px}
#game:not(.active) .statbox,#game:not(.active) .shotclock,#game:not(.active) .bottom-hud{opacity:0}
#game:not(.active) .touch-controls,#game:not(.active) .touch-actions{display:none!important}
#game:not(.active) #tags{display:none}
#game:not(.active) .side-meter{display:none!important}

/* roster select */
.select-overlay{position:absolute;z-index:10;inset:0;display:flex;flex-direction:column;padding:20px clamp(16px,4vw,52px) 16px;background:radial-gradient(ellipse at 74% 10%,#19342d 0%,#091917 42%,#061110 100%);overflow-y:auto;transition:opacity .3s,visibility .3s}
.select-overlay.hidden{opacity:0;visibility:hidden;pointer-events:none}
.select-top{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;flex-wrap:wrap}
.select-kicker{display:flex;align-items:center;gap:9px;color:var(--lime);font-weight:900;font-size:9px;letter-spacing:.25em}
.select-kicker:before{content:"";width:23px;height:1px;background:var(--lime)}
.select-title{font-size:clamp(30px,4.6vw,58px);line-height:.88;letter-spacing:-.065em;margin:8px 0 6px;font-weight:950}
.select-title span{color:var(--lime)}
.select-sub{color:#9bafa0;font-size:10px;letter-spacing:.08em;margin:0}
.steps{display:flex;gap:18px;color:#6f8377;font-size:8px;font-weight:900;letter-spacing:.16em;white-space:nowrap}
.steps .on{color:var(--lime)}
.steps .done{color:#d5e2d2}
.lineup-bar{display:flex;gap:8px;margin:15px 0 12px}
.slot{flex:1;min-height:42px;border:1px dashed #ffffff2b;border-radius:5px;padding:6px 10px;display:flex;flex-direction:column;justify-content:center;background:#08161499;transition:.2s}
.slot.filled{border-style:solid;border-color:#d8ff3e5c;background:#0c2018c9}
.slot.rival.filled{border-color:#ff7a5f66;background:#22100fbd}
.slot span{color:#7e9184;font-size:7px;font-weight:900;letter-spacing:.17em}
.slot b{font-size:11px;font-weight:950;letter-spacing:.04em;color:#e7efe3;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.slot.filled b{color:var(--lime)}
.slot.rival.filled b{color:#ff9a85}
.roster-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:7px}
.star-card{position:relative;overflow:hidden;text-align:left;min-height:88px;border:1px solid #ffffff1f;border-radius:5px;background:linear-gradient(145deg,#0e211e 0%,#091715 75%);padding:9px 10px;transition:transform .12s,border-color .12s,background .12s}
.star-card:hover{transform:translateY(-1px);border-color:#ffffff5e}
.star-card .snum{position:absolute;right:7px;top:0;font-size:27px;font-weight:950;line-height:1;color:#ffffff12;letter-spacing:-.06em}
.star-card .srating{font-size:12px;font-weight:950;color:var(--lime);letter-spacing:.02em}
.star-card .srating small{font-size:7px;color:#829587;margin-left:2px;font-weight:800}
.star-card strong{display:block;font-size:11px;line-height:1.06;margin:7px 0 3px;letter-spacing:.01em;color:#eef3e9;position:relative;z-index:1}
.star-card .meta{font-size:7px;color:#8fa397;letter-spacing:.11em;font-weight:800}
.star-card .trait{font-size:7px;color:#6f8376;letter-spacing:.12em;font-weight:900;margin-top:5px}
.star-card.picked{border-color:var(--lime);background:linear-gradient(145deg,#20331a 0%,#0d1c12 78%);box-shadow:0 0 0 1px #d8ff3e4d,0 6px 18px #0006}
.star-card.picked:after{content:"YOUR SQUAD";position:absolute;right:6px;bottom:5px;font-size:6px;letter-spacing:.12em;font-weight:950;color:#09110b;background:var(--lime);padding:2px 4px;border-radius:2px}
.star-card.rival{border-color:#ff7a5f;background:linear-gradient(145deg,#301614 0%,#1b0d0c 78%);box-shadow:0 0 0 1px #ff7a5f3d}
.star-card.rival:after{content:"RIVALS";position:absolute;right:6px;bottom:5px;font-size:6px;letter-spacing:.12em;font-weight:950;color:#1b0d0c;background:#ff7a5f;padding:2px 4px;border-radius:2px}
.star-card.locked{opacity:.24;pointer-events:none;filter:grayscale(.5)}
.select-foot{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-top:13px}
.select-hint{font-size:8px;color:#91a095;letter-spacing:.08em;line-height:1.5;max-width:360px}
.select-foot .play-btn{padding:13px 18px;font-size:9px}
.select-foot .ghost-btn{padding:11px 14px;font-size:9px}
#select-next:disabled{opacity:.3;cursor:not-allowed;transform:none;filter:none}

@media(max-width:700px){
  .topbar{padding:13px 15px}
  .brand{font-size:10px}
  .brandmark{width:28px;height:28px}
  .live{font-size:7px;letter-spacing:.13em}
  .scoreboard{top:58px;gap:12px;padding:8px 12px}
  .team{min-width:39px}
  .team strong{font-size:19px}
  .clock{padding:0 10px}
  .clock strong{font-size:16px}
  .statbox{top:114px;left:15px;gap:5px}
  .stat{min-width:52px;padding:6px 8px}
  .stat span{font-size:7px}
  .stat b{font-size:12px}
  .shotclock{top:116px;right:15px;font-size:8px;gap:6px}
  .shotclock b{font-size:18px}
  .bottom-hud{bottom:13px;left:14px;right:14px}
  .tips{display:none}
  .touch-controls{display:flex}
  .touch-actions{display:grid}
  .mobile-tip{display:block}
  .overlay{background:linear-gradient(90deg,#071313e9,#071313a8)}
  .card{margin:0;align-self:start;margin-top:16vh}
  .card h1{font-size:clamp(54px,15vw,80px)}
  .deck{max-width:305px;font-size:13px}
  .rules{gap:15px}
  .rule{font-size:8px}
  .pause-pill{top:94px;right:15px;padding:7px 9px}
  .toast{top:33%}
  .select-overlay{padding:16px 14px 12px}
  .select-top{align-items:flex-start}
  .steps{gap:10px;font-size:7px;margin-top:5px}
  .roster-grid{grid-template-columns:repeat(2,1fr);gap:6px}
  .star-card{min-height:78px;padding:8px 9px}
  .star-card strong{font-size:11px}
  .slot{min-height:38px;padding:5px 8px}
  .slot b{font-size:10px}
  .select-foot{gap:8px}
  .select-hint{font-size:7px;max-width:100%}
  .side-meter{width:62px}
  .sm-track{height:100px;width:10px}
  .sm-caption{font-size:6px}
  .tag{font-size:7px;padding:2px 4px}
  .tag small{font-size:6px}
  #shot-feedback{font-size:19px}
  .touch-actions{right:14px;bottom:108px}
  .mini-btn{width:56px;height:32px;font-size:7px}
  .shoot-touch{width:76px;height:76px}
  .stick{width:104px;height:104px}
}
@media(max-height:640px){
  .card{margin-top:5vh}
  .card h1{font-size:48px;margin:10px 0}
  .deck{margin-bottom:12px;font-size:12px}
  .rules{margin-top:12px;padding-top:10px}
  .build-tag{margin-bottom:8px}
  .select-overlay{padding-top:12px}
  .select-title{font-size:30px}
  .lineup-bar{margin:8px 0}
  .star-card{min-height:74px}
  .select-sub{display:none}
}

input.command:
cp /tmp/opencode/base.js game.js
cat >> game.js <<'EOF'

/* ================================================================== */
/*  3v3 ROSTER + CHARACTERS                                           */
/* ================================================================== */

const ROSTER = [
  { id: 'curry',    name: 'Stephen Curry',          short: 'CURRY',   pos: 'PG', rating: 96, shoot: 99, speed: 93, height: 1.88, number: '30', skin: 0x8a5a3d, trait: 'SHARPSHOOTER' },
  { id: 'lebron',   name: 'LeBron James',           short: 'JAMES',   pos: 'SF', rating: 97, shoot: 88, speed: 92, height: 2.06, number: '23', skin: 0x70452c, trait: 'ALL-AROUND' },
  { id: 'durant',   name: 'Kevin Durant',           short: 'DURANT',  pos: 'SF', rating: 95, shoot: 95, speed: 87, height: 2.11, number: '7',  skin: 0x5b3722, trait: 'SCORER' },
  { id: 'giannis',  name: 'Giannis Antetokounmpo',  short: 'GIANNIS', pos: 'PF', rating: 96, shoot: 78, speed: 94, height: 2.11, number: '34', skin: 0x5d3823, trait: 'FREAK' },
  { id: 'jokic',    name: 'Nikola Jokic',           short: 'JOKIC',   pos: 'C',  rating: 97, shoot: 89, speed: 74, height: 2.11, number: '15', skin: 0xd7b08b, trait: 'PLAYMAKER' },
  { id: 'luka',     name: 'Luka Doncic',            short: 'DONCIC',  pos: 'PG', rating: 96, shoot: 92, speed: 85, height: 2.01, number: '77', skin: 0xd8b08a, trait: 'SHOT CREATOR' },
  { id: 'tatum',    name: 'Jayson Tatum',           short: 'TATUM',   pos: 'SF', rating: 95, shoot: 91, speed: 88, height: 2.03, number: '0',  skin: 0x6d452d, trait: 'TWO-WAY' },
  { id: 'sga',      name: 'Shai Gilgeous-Alexander', short: 'SGA',    pos: 'PG', rating: 95, shoot: 89, speed: 93, height: 1.98, number: '2',  skin: 0x6b432c, trait: 'SLASHER' },
  { id: 'ant',      name: 'Anthony Edwards',        short: 'EDWARDS', pos: 'SG', rating: 94, shoot: 90, speed: 95, height: 1.93, number: '5',  skin: 0x5a3520, trait: 'ATHLETE' },
  { id: 'book',     name: 'Devin Booker',           short: 'BOOKER',  pos: 'SG', rating: 93, shoot: 92, speed: 89, height: 1.96, number: '1',  skin: 0xc69a72, trait: 'BUCKET' },
  { id: 'dame',     name: 'Damian Lillard',         short: 'LILLARD', pos: 'PG', rating: 92, shoot: 94, speed: 88, height: 1.88, number: '0',  skin: 0x69422b, trait: 'LOGO RANGE' },
  { id: 'wemby',    name: 'Victor Wembanyama',      short: 'WEMBY',   pos: 'C',  rating: 92, shoot: 86, speed: 82, height: 2.24, number: '1',  skin: 0x7b5137, trait: 'UNICORN' }
];
const STAR_BY_ID = Object.fromEntries(ROSTER.map(p => [p.id, p]));

const HOME_COLOR = 0xd8ff3e;
const HOME_ACCENT = 0x17240f;
const AWAY_COLOR = 0xd64b38;
const AWAY_ACCENT = 0x2a1512;

const numberCache = {};
function numberTex(n) {
  if (!numberCache[n]) numberCache[n] = makeNumberTexture(n);
  return numberCache[n];
}

function makeCharacter(jersey, accent, skin, number, height, isDef, team) {
  const root = new THREE.Group();
  const jerseyMat = new THREE.MeshStandardMaterial({ color: jersey, roughness: 0.55, metalness: 0.08 });
  const shortsMat = new THREE.MeshStandardMaterial({ color: accent, roughness: 0.62, metalness: 0.05 });
  const skinMat = new THREE.MeshStandardMaterial({ color: skin, roughness: 0.72 });
  const shoeMat = new THREE.MeshStandardMaterial({ color: isDef ? 0x281b19 : 0x1b211c, roughness: 0.55 });

  const torso = new THREE.Mesh(new THREE.CapsuleGeometry(0.265, 0.4, 5, 12), jerseyMat);
  torso.position.y = 1.24; torso.scale.z = 0.78; torso.castShadow = true; root.add(torso);

  const shorts = new THREE.Mesh(new THREE.CylinderGeometry(0.275, 0.315, 0.38, 12), shortsMat);
  shorts.position.y = 0.9; shorts.scale.z = 0.84; shorts.castShadow = true; root.add(shorts);

  const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.085, 0.095, 0.1, 8), skinMat);
  neck.position.y = 1.56; root.add(neck);

  const head = new THREE.Mesh(new THREE.SphereGeometry(0.185, 14, 12), skinMat);
  head.position.y = 1.75; head.scale.set(0.94, 1.03, 0.96); head.castShadow = true; root.add(head);

  // hair cap
  const hairMat = new THREE.MeshStandardMaterial({ color: 0x171311, roughness: 0.95 });
  const hair = new THREE.Mesh(new THREE.SphereGeometry(0.191, 12, 8, 0, Math.PI * 2, 0, Math.PI * 0.52), hairMat);
  hair.position.y = 1.76; hair.scale.set(0.96, 1.0, 0.99); root.add(hair);

  // eyes / face markers so players read from the front
  const eyeMat = new THREE.MeshBasicMaterial({ color: 0x12100d });
  for (const s of [-1, 1]) {
    const eye = new THREE.Mesh(new THREE.SphereGeometry(0.019, 6, 5), eyeMat);
    eye.position.set(s * 0.065, 1.775, -0.168);
    root.add(eye);
  }

  const band = new THREE.Mesh(new THREE.CylinderGeometry(0.193, 0.193, 0.055, 14), new THREE.MeshStandardMaterial({ color: accent, roughness: 0.6 }));
  band.position.y = 1.795; band.scale.z = 0.98; root.add(band);

  const numMat = new THREE.MeshBasicMaterial({ map: numberTex(number), transparent: true, toneMapped: false, side: THREE.DoubleSide });
  for (const z of [-0.311, 0.311]) {
    const num = new THREE.Mesh(new THREE.PlaneGeometry(0.23, 0.23), numMat);
    num.position.set(0, 1.28, z);
    if (z < 0) num.rotation.y = Math.PI;
    root.add(num);
  }

  const arms = [];
  for (const side of [-1, 1]) {
    const shoulder = new THREE.Group();
    shoulder.position.set(side * 0.36, 1.44, 0);
    shoulder.rotation.z = side * -0.1;
    const upper = limb(0.066, 0.34, skinMat);
    upper.position.y = -0.17; upper.castShadow = true; shoulder.add(upper);
    const elbow = new THREE.Group();
    elbow.position.y = -0.33;
    const lower = limb(0.056, 0.3, skinMat);
    lower.position.y = -0.15; lower.castShadow = true; elbow.add(lower);
    const hand = new THREE.Mesh(new THREE.SphereGeometry(0.072, 8, 6), skinMat);
    hand.position.y = -0.32; elbow.add(hand);
    shoulder.add(elbow);
    root.add(shoulder);
    arms.push({ shoulder, elbow });
  }

  const legs = [];
  for (const side of [-1, 1]) {
    const hip = new THREE.Group();
    hip.position.set(side * 0.155, 0.83, 0);
    const thigh = limb(0.09, 0.36, skinMat);
    thigh.position.y = -0.18; thigh.castShadow = true; hip.add(thigh);
    const knee = new THREE.Group();
    knee.position.y = -0.35;
    const shin = limb(0.073, 0.34, skinMat);
    shin.position.y = -0.17; shin.castShadow = true; knee.add(shin);
    const shoe = new THREE.Mesh(new THREE.BoxGeometry(0.155, 0.1, 0.275), shoeMat);
    shoe.position.set(0, -0.37, -0.045); shoe.castShadow = true; knee.add(shoe);
    hip.add(knee);
    root.add(hip);
    legs.push({ hip, knee });
  }

  const ring = new THREE.Mesh(
    new THREE.RingGeometry(0.44, 0.53, 40),
    new THREE.MeshBasicMaterial({
      color: isDef ? 0xff6f55 : 0xd8ff3e,
      transparent: true, opacity: isDef ? 0.18 : 0.34,
      side: THREE.DoubleSide, depthWrite: false, toneMapped: false
    })
  );
  ring.rotation.x = -Math.PI / 2;
  ring.position.y = 0.012;
  root.add(ring);

  root.scale.setScalar(height / 1.95);
  return { root, arms, legs, torso, head, ring };
}

function limb(radius, length, mat, segs = 7) {
  const geo = new THREE.CapsuleGeometry(radius, Math.max(0.02, length - radius * 2), 4, segs);
  return new THREE.Mesh(geo, mat);
}

/* ================================================================== */
/*  ACTORS                                                            */
/* ================================================================== */

const homeTeam = { color: HOME_COLOR, accent: HOME_ACCENT, actors: [] };
const awayTeam = { color: AWAY_COLOR, accent: AWAY_ACCENT, actors: [] };
let actors = [];
let activeIndex = 0;
let homeStars = [];
let awayStars = [];
let teamsBuilt = false;

const tagsEl = document.getElementById('tags');

function makeActor(star, team, teamIndex) {
  const isAway = team === 'away';
  const rig = makeCharacter(
    isAway ? AWAY_COLOR : HOME_COLOR,
    isAway ? AWAY_ACCENT : HOME_ACCENT,
    star.skin, star.number, star.height, isAway, team
  );
  scene.add(rig.root);
  const el = document.createElement('div');
  el.className = `tag ${team}`;
  el.innerHTML = `${star.short}<small>${star.rating}</small>`;
  tagsEl.appendChild(el);
  return {
    star, team, teamIndex, rig, tag: el,
    x: 0, z: 1.2, vx: 0, vz: 0, phase: Math.random() * 6,
    radius: 0.45,
    speed: 3.05 + (star.speed - 70) * 0.022,
    spot: { x: 0, z: -5 },
    cutTimer: 0, cutCooldown: 2 + Math.random() * 3,
    receive: 0, screened: 0, screenHold: 0,
    moveTimer: 0, moveType: '', moveCooldown: 0,
    points: 0, shotFeedback: 0, facing: 0
  };
}

function disposeTeam() {
  for (const a of actors) {
    scene.remove(a.rig.root);
    a.rig.root.traverse(o => {
      if (o.geometry) o.geometry.dispose();
      if (o.material && o.material.map) { /* keep shared textures */ }
    });
    a.tag.remove();
  }
  actors = [];
  homeTeam.actors = [];
  awayTeam.actors = [];
  tagsEl.innerHTML = '';
  teamsBuilt = false;
}

const HOME_SPOTS = [
  { x: -5.7, z: -6.0 },
  { x: 5.7, z: -6.0 },
  { x: -6.4, z: -1.4 },
  { x: 6.4, z: -1.4 },
  { x: 0, z: -8.6 }
];

function buildTeams(home, away) {
  disposeTeam();
  homeStars = home;
  awayStars = away;
  for (let i = 0; i < 3; i++) {
    const h = makeActor(home[i], 'home', i);
    const a = makeActor(away[i], 'away', i);
    homeTeam.actors.push(h);
    awayTeam.actors.push(a);
    actors.push(h, a);
  }
  teamsBuilt = true;
  resetFormation(true);
}

function resetFormation(initial = false) {
  const home = homeTeam.actors, away = awayTeam.actors;
  if (!home.length) return;
  const active = home[activeIndex] || home[0];
  active.x = 0; active.z = 1.5; active.vx = active.vz = 0;
  const mates = home.filter(a => a !== active);
  mates[0].x = -5.7; mates[0].z = -5.9; mates[0].vx = mates[0].vz = 0;
  if (mates[1]) { mates[1].x = 5.7; mates[1].z = -5.9; mates[1].vx = mates[1].vz = 0; }
  home.forEach((a, i) => { a.cutTimer = 0; a.receive = 0; a.screened = 0; a.screenHold = 0; a.spot = { x: i === 0 ? 0 : (i === 1 ? -5.7 : 5.7), z: -5.9 }; });
  away[0].x = 0; away[0].z = -1.3;
  away[1].x = -4.5; away[1].z = -7.0;
  away[2].x = 4.5; away[2].z = -7.0;
  for (const a of away) { a.vx = a.vz = 0; a.screened = 0; a.screenHold = 0; a.receive = 0; }
  state.screen = null;
  state.pass = null;
  state.shot = null;
  state.rebound = null;
  state.pressure = 0;
  state.charging = false;
  state.charge = 0;
  state.chargeDir = 1;
  state.shootAnim = 0;
  ballVel.set(0, 0, 0);
  updateBallAnchor(true);
  if (initial) { state.shotClock = 24; }
}

function updateBallAnchor(instant = false) {
  const a = homeTeam.actors[activeIndex] || homeTeam.actors[0];
  if (!a) return;
  if (state.mode === 'menu' || instant) {
    ball.position.set(a.x + 0.4, 0.7, a.z + 0.1);
  }
}
