**UpdateGame**:
```
function updateGame(dt,t){
 if(mode==='playing'){
  gameTime-=dt; shotClock-=dt;
  if(gameTime<=0){...endGame;return}
  if(shotClock<=0) shotClockViolation();
  updateActive(dt);
  for (const a of homeTeam.actors) if(a!==activeActor()) updateHomeAI(...)
  awayTeam.actors.forEach...
  separateActors();
  updatePressure(dt);
  if(state.charging){ charge += dt*0.9*dir; ...}
