  if(state.screen){ state.screen.timer+=dt; if(set&&timer>1.9) endScreen(true); if(!set&&timer>3.5) {endScreen(true); showToast('SCREEN BROKEN',true);} }
  state.screenCooldown=Math.max(0,state.screenCooldown-dt)
