    tx += (active.x - tx) * 0.08;
    tz += (active.z - tz) * 0.08;
  }
  const slow = d.screenHold > 0 ? 0.35 : 1;
  moveToward(d, tx, tz, d.speed * slow, dt, 4.1);
}

